#### REQ-LENS-004-007: Okta Application Configuration

**Status**: Mandatory
**Rationale**: Consistent Okta app setup across environments

**Requirements**:
- Create Okta SAML app: "Lenses.io - {environment}"
- Application visibility: Hidden (users access via direct URL)
- User assignment: Assign Okta groups (platform_admins, developers, etc.)
- Sign-On Policy: Lenses.io - MFA Required (REQ-LENS-004-002)
- Attribute Statements:
  - email → user.email (NameID)
  - firstName → user.firstName
  - lastName → user.lastName
  - memberOf → user.groups (filter: starts with "okta_lenses_")
- Enable SCIM provisioning (if supported by Lenses.io version)

**Implementation**:
```hcl
# Okta SAML Application Configuration
# File: terraform/okta/lenses-saml-app.tf

terraform {
  required_providers {
    okta = {
      source  = "okta/okta"
      version = "~> 4.0"
    }
  }
}

variable "environment" {
  description = "Environment name (dev, staging, prod)"
  type        = string
}

variable "lenses_base_url" {
  description = "Base URL for Lenses.io"
  type        = string
  default     = "https://lenses.${var.environment}.company.com"
}

# Data sources for Okta groups
data "okta_group" "platform_admins" {
  name = "okta_lenses_platform_admins"
}

data "okta_group" "developers_claims" {
  name = "okta_lenses_developers_claims"
}

data "okta_group" "developers_enrollment" {
  name = "okta_lenses_developers_enrollment"
}

data "okta_group" "developers_pharmacy" {
  name = "okta_lenses_developers_pharmacy"
}

data "okta_group" "developers_provider" {
  name = "okta_lenses_developers_provider"
}

data "okta_group" "developers_analytics" {
  name = "okta_lenses_developers_analytics"
}

data "okta_group" "prod_developers" {
  name = "okta_lenses_prod_developers"
}

data "okta_group" "data_stewards" {
  name = "okta_lenses_data_stewards"
}

data "okta_group" "read_only" {
  name = "okta_lenses_read_only"
}

# Create Okta SAML Application
resource "okta_app_saml" "lenses" {
  label                    = "Lenses.io - ${var.environment}"
  status                   = "ACTIVE"

  # Application visibility
  hide_ios                 = true
  hide_web                 = true  # Hidden, users access via direct URL

  # SAML Configuration
  sso_url                  = "${var.lenses_base_url}/api/saml/callback"
  recipient                = "${var.lenses_base_url}/api/saml/callback"
  destination              = "${var.lenses_base_url}/api/saml/callback"
  audience                 = var.lenses_base_url
  subject_name_id_template = "${user.email}"
  subject_name_id_format   = "urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress"

  # Response and Assertion Configuration
  response_signed          = true
  assertion_signed         = true
  signature_algorithm      = "RSA_SHA256"
  digest_algorithm         = "SHA256"
  honor_force_authn        = true
  authn_context_class_ref  = "urn:oasis:names:tc:SAML:2.0:ac:classes:PasswordProtectedTransport"

  # Single Logout
  slo:
    enabled   = true
    url       = "${var.lenses_base_url}/api/saml/logout"
    binding   = "HTTP-Redirect"

  # Attribute Statements
  attribute_statements {
    name         = "email"
    type         = "EXPRESSION"
    namespace    = "urn:oasis:names:tc:SAML:2.0:attrname-format:basic"
    values       = ["user.email"]
  }

  attribute_statements {
    name         = "firstName"
    type         = "EXPRESSION"
    namespace    = "urn:oasis:names:tc:SAML:2.0:attrname-format:basic"
    values       = ["user.firstName"]
  }

  attribute_statements {
    name         = "lastName"
    type         = "EXPRESSION"
    namespace    = "urn:oasis:names:tc:SAML:2.0:attrname-format:basic"
    values       = ["user.lastName"]
  }

  attribute_statements {
    name         = "memberOf"
    type         = "GROUP"
    namespace    = "urn:oasis:names:tc:SAML:2.0:attrname-format:basic"
    filter_type  = "STARTS_WITH"
    filter_value = "okta_lenses_"
  }
}

# Assign groups to SAML application
resource "okta_app_group_assignments" "lenses_groups" {
  app_id = okta_app_saml.lenses.id

  group {
    id = data.okta_group.platform_admins.id
    priority = 1
  }

  group {
    id = data.okta_group.developers_claims.id
    priority = 2
  }

  group {
    id = data.okta_group.developers_enrollment.id
    priority = 3
  }

  group {
    id = data.okta_group.developers_pharmacy.id
    priority = 4
  }

  group {
    id = data.okta_group.developers_provider.id
    priority = 5
  }

  group {
    id = data.okta_group.developers_analytics.id
    priority = 6
  }

  group {
    id = data.okta_group.prod_developers.id
    priority = 7
  }

  group {
    id = data.okta_group.data_stewards.id
    priority = 8
  }

  group {
    id = data.okta_group.read_only.id
    priority = 9
  }
}

# Outputs
output "lenses_saml_app_id" {
  description = "Okta SAML App ID for Lenses.io"
  value       = okta_app_saml.lenses.id
}

output "lenses_saml_metadata_url" {
  description = "SAML metadata URL for Lenses.io"
  value       = "https://company.okta.com/app/${okta_app_saml.lenses.id}/sso/saml/metadata"
}
```
